             <div class="choices">
               <label class="choice" for="q1-python">
                 <input id="q1-python" name="q1" type="checkbox" value="Python">
                 <span class="choice-text">Python</span>
               </label>
               <label class="choice" for="q1-html">
                 <input id="q1-html" name="q1" type="checkbox" value="HTML">
                 <span class="choice-text">HTML</span>
               </label>
               <label class="choice" for="q1-java">
                 <input id="q1-java" name="q1" type="checkbox" value="Java">
                 <span class="choice-text">Java</span>
               </label>
               <label class="choice" for="q1-css">
                 <input id="q1-css" name="q1" type="checkbox" value="CSS">
                 <span class="choice-text">CSS</span>
               </label>
             </div>
           </fieldset>
         </div>

         <div class="form-field">
           <fieldset>
             <legend>2. Which of these are scripting or scripting-friendly languages?</legend>
             <div class="choices">
               <label class="choice" for="q2-javascript">
                 <input id="q2-javascript" name="q2" type="checkbox" value="JavaScript">
                 <span class="choice-text">JavaScript</span>
               </label>
               <label class="choice" for="q2-rust">
                 <input id="q2-rust" name="q2" type="checkbox" value="Rust">
                 <span class="choice-text">Rust</span>
               </label>
               <label class="choice" for="q2-python">
                 <input id="q2-python" name="q2" type="checkbox" value="Python">
                 <span class="choice-text">Python</span>
               </label>
               <label class="choice" for="q2-sql">
                 <input id="q2-sql" name="q2" type="checkbox" value="SQL">
                 <span class="choice-text">SQL</span>
               </label>
             </div>
           </fieldset>
         </div>

         <div class="form-field">
           <fieldset>
             <legend>3. Which of these are used to mark up or structure content?</legend>
             <div class="choices">
               <label class="choice" for="q3-html">
                 <input id="q3-html" name="q3" type="checkbox" value="HTML">
                 <span class="choice-text">HTML</span>
               </label>
               <label class="choice" for="q3-css">
                 <input id="q3-css" name="q3" type="checkbox" value="CSS">
                 <span class="choice-text">CSS</span>
               </label>
               <label class="choice" for="q3-markdown">
                 <input id="q3-markdown" name="q3" type="checkbox" value="Markdown">
                 <span class="choice-text">Markdown</span>
               </label>
               <label class="choice" for="q3-go">
                 <input id="q3-go" name="q3" type="checkbox" value="Go">
                 <span class="choice-text">Go</span>
               </label>
             </div>
           </fieldset>
         </div>

         <p class="score-panel" id="quiz-result" aria-live="polite">
           Your score will appear here after you submit.
         </p>

         <div class="actions">
           <button type="submit">Submit quiz</button>
         </div>
       </form>
     </section>
   </main>

   <script>
     const answers = {
       q1: new Set(["Python", "Java"]),
       q2: new Set(["JavaScript", "Python", "SQL"]),
       q3: new Set(["HTML", "CSS", "Markdown"])
     };

     const form = document.getElementById("quiz-form");
     const result = document.getElementById("quiz-result");

     function getSelections(questionName) {
       return Array.from(form.querySelectorAll(`input[name="${questionName}"]:checked`)).map((input) => input.value);
     }

     function isExactMatch(selections, correctAnswers) {
       if (selections.length !== correctAnswers.size) {
         return false;
       }

       return selections.every((selection) => correctAnswers.has(selection));
     }

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const score = Object.keys(answers).reduce((total, questionName) => {
         const selections = getSelections(questionName);
         return total + (isExactMatch(selections, answers[questionName]) ? 1 : 0);
       }, 0);

       result.textContent = `You scored ${score} out of ${Object.keys(answers).length}.`;
     });
   </script>
