     .choice {
       display: flex;
       align-items: flex-start;
       gap: 0.75rem;
       padding: 0.9rem 1rem;
       border: 1px solid rgba(138, 180, 255, 0.18);
       border-radius: 14px;
       background: rgba(11, 16, 32, 0.45);
       transition: border-color 150ms ease, transform 150ms ease, background-color 150ms ease;
       cursor: pointer;
     }

     .choice:hover {
       border-color: rgba(138, 180, 255, 0.35);
       transform: translateY(-1px);
       background: rgba(17, 25, 48, 0.8);
