       cursor: pointer;
       transition: transform 150ms ease, box-shadow 150ms ease;
     }

     button:hover {
       transform: translateY(-1px);
       box-shadow: 0 16px 32px rgba(138, 180, 255, 0.28);
     }

     button:focus-visible {
       outline: 3px solid #fff;
       outline-offset: 3px;
